"""Class 6 Maths, chapter 2: Lines and Angles. Run: python3 gen_angles.py  (writes the recipe; Build-Lessons.bat compiles it)."""
import json, os
OUT=os.environ.get("RECIPE_OUT","/tmp/ss-build/content/recipes/class6/cbse-6-lines-and-angles.json")
P=[];ST=[]
def part(*a): P.append(list(a))
def size_for(text,size): return max(16,int(min(size,780/(len(text)*0.72))))
def L(text,id,y=455,size=34,color="#1F3B6E",x=450,anchor="middle"): part("label",id,{"text":text,"x":x,"y":y,"size":size_for(text,size),"color":color,"anchor":anchor})
def step(id,sec,en,ta,do=None,q=None):
    s={"id":id,"section":sec,"say":[en,ta],"do":do or []}
    if q: s["q"]=q
    ST.append(s)
def Q(stem,ta,ok,opts,e,eta): return {"s":[stem,ta],"ok":ok,"o":opts,"e":[e,eta]}
def qs(id,sec,en,ta,stem,tstem,ok,opts,e,eta,do=None): step(id,sec,en,ta,do or [],Q(stem,tstem,ok,opts,e,eta))
def O(a,ta,w=None,tw=None): return [a,ta,w,tw] if w else [a,ta]
CL=["clear","","",{}]
def sh(ids,at=0.1,gap=0.05,verb="show",ms=300): return [[verb,i,round(at+k*gap,3),{"ms":ms}] for k,i in enumerate(ids)]
def DOT(id,x,y,label,dx=0,dy=-18,color="#E53935"):
    part("raw",id,{"kind":"circle","cx":x,"cy":y,"r":8,"fill":color,"stroke":"#B71C1C","width":3}); L(label,"t"+id,y=y+dy+8,x=x+dx,size=30,color="#16253F")
def SEG(id,x1,y1,x2,y2,color="#16253F",w=7): part("raw",id,{"kind":"line","x1":x1,"y1":y1,"x2":x2,"y2":y2,"stroke":color,"width":w})
def ARR(id,x1,y1,x2,y2,color="#16253F",w=7): part("raw",id,{"kind":"arrow","x1":x1,"y1":y1,"x2":x2,"y2":y2,"stroke":color,"width":w})
BL,OR,GR,CY,RD="#1E88E5","#E65100","#2E7D32","#FFD166","#C0392B"
S1,S2,S3,S4,S5,S6,S7,S8="1 Point, line and ray","2 What is an angle","3 Comparing angles","4 Straight and right angles","5 Acute and obtuse","6 Measuring in degrees","7 Using a protractor","8 Types and measures"
PR,MX="Extra practice","Mixed practice"
