part("angle","st",{"cx":450,"cy":330,"r":260,"a1":0,"a2":180,"color":BL,"fill":"#BBDEFB","arc":90})
L("A","tStA",y=370,x=170,size=32); L("O","tStO",y=375,x=450,size=32); L("B","tStB",y=370,x=730,size=32)
