L("acute","tAc",y=390,x=190,size=30,color=GR); L("right","tRg",y=390,x=440,size=30,color=RD); L("obtuse","tOb",y=390,x=640,size=30,color=OR)
L("Acute means sharp.  Obtuse means blunt.","tMean",y=450,size=30,color="#1F3B6E")
L("Acute: less than a quarter turn","tAcD",y=110,size=28,color=GR); L("Obtuse: more than a quarter turn, less than a half turn","tObD",y=150,size=26,color=OR)
part("pie","wh",{"n":12,"cx":450,"cy":270,"r":170,"wholeFill":"#FFF8E1","wholeStroke":"#8D6E63"})
L("A full turn is divided into 360 equal parts. Each part is 1 degree (1°)","tDeg",y=470,size=26,color="#1F3B6E")
L("Full turn = 360°","tDeg2",y=70,size=30,color=RD); L("Half turn (straight angle) = 180°","tDeg2b",y=110,size=30,color=RD); L("Quarter turn (right angle) = 90°","tDeg2c",y=150,size=30,color=RD)
part("angle","d30",{"cx":300,"cy":350,"r":250,"a1":0,"a2":30,"color":BL,"fill":"#BBDEFB","arc":120,"label":"30°"})
