part("angle","pb",{"cx":450,"cy":370,"r":290,"a1":0,"a2":120,"color":OR,"fill":"#FFE0B2","arc":130,"label":"120°"})
L("Draw an arm, place the protractor, mark 60°","tDraw",y=440,size=28,color="#1F3B6E"); L("Remove it and join the mark to the vertex","tDraw2",y=480,size=28,color="#1F3B6E")
L("Acute: more than 0° and less than 90°","tT1",y=120,size=30,color=GR); L("Right: exactly 90°","tT2",y=180,size=30,color=RD); L("Obtuse: more than 90°, less than 180°","tT3",y=240,size=30,color=OR)
L("Straight: exactly 180°","tT4",y=300,size=30,color="#1E5FA8"); L("Reflex: more than 180°, less than 360°","tT5",y=360,size=30,color="#8E24AA"); L("Complete: exactly 360°","tT6",y=420,size=30,color="#37474F")
